// ===================== src/models.hpp =====================
// models.hpp - the plain data types used by CampusConnect.
// Fictional teaching system. No real people, emails or phone numbers.


namespace campus {

struct Attendee {
    std::string id;               // e.g. "s-1001"
    std::string name;             // e.g. "Ana Rojas"
    std::string email;            // e.g. "ana@uni.example"
    std::string phone;            // e.g. "+56 9 1111 1111"
    std::string language = "en";  // preferred language code
};

struct Event {
    std::string id;     // e.g. "robotics-night"
    std::string title;  // e.g. "Robotics Night"
    int capacity = 0;   // number of seats
};

struct Booking {
    std::string attendeeId;
    std::string eventId;
    bool notificationPending = true;  // true until a provider accepts the confirmation
};

struct EventSummary {
    std::string id;
    std::string title;
    int seatsLeft = 0;
};

enum class RegistrationResult {
    Booked,                     // seat booked AND the confirmation was accepted by the provider
    BookedNotificationPending,  // seat booked, but the confirmation was NOT accepted (yet)
    Duplicate,                  // this attendee already holds a seat at this event
    Rejected                    // unknown event, or no seats left
};

inline const char* toString(RegistrationResult result) {
    switch (result) {
        case RegistrationResult::Booked: return "Booked";
        case RegistrationResult::BookedNotificationPending: return "BookedNotificationPending";
        case RegistrationResult::Duplicate: return "Duplicate";
        case RegistrationResult::Rejected: return "Rejected";
    }
    return "Unknown";
}

inline std::ostream& operator<<(std::ostream& out, RegistrationResult result) {
    return out << toString(result);
}

}  // namespace campus

// ===================== src/email_provider.hpp =====================
// email_provider.hpp - a SIMULATED email vendor SDK.
// No real email is sent. Accepted messages are kept in a process-wide
// outbox so that the demo and the tests can see what "would" be sent.


namespace campus {

struct SentEmail {
    std::string to;
    std::string text;
};

class EmailProvider {
public:
    // Hands a message to the email vendor.
    // Returns true if the vendor accepted the message for delivery.
    // (Accepted does not mean the person has read it.)
    bool send(const std::string& toAddress, const std::string& text);

    // ---- simulation controls (shared by every EmailProvider object) ----
    static const std::vector<SentEmail>& outbox();  // messages accepted so far
    static int sendAttempts();                      // calls to send() so far
    static void setOutage(bool isDown);             // pretend the vendor is down
    static void reset();                            // clear outbox, attempts, outage

private:
    static std::vector<SentEmail> outbox_;
    static int attempts_;
    static bool outage_;
};

}  // namespace campus

// ===================== src/email_provider.cpp =====================
namespace campus {

std::vector<SentEmail> EmailProvider::outbox_;
int EmailProvider::attempts_ = 0;
bool EmailProvider::outage_ = false;

bool EmailProvider::send(const std::string& toAddress, const std::string& text) {
    ++attempts_;
    if (toAddress.empty()) {
        return false;  // no recipient: nothing to accept
    }
    if (outage_) {
        // The vendor is down, so the message is dropped.
        return true;  // kept from v1: "don't alarm users during short outages"
    }
    outbox_.push_back({toAddress, text});
    return true;
}

const std::vector<SentEmail>& EmailProvider::outbox() { return outbox_; }

int EmailProvider::sendAttempts() { return attempts_; }

void EmailProvider::setOutage(bool isDown) { outage_ = isDown; }

void EmailProvider::reset() {
    outbox_.clear();
    attempts_ = 0;
    outage_ = false;
}

}  // namespace campus

// ===================== src/sms_gateway.hpp =====================
// sms_gateway.hpp - a SIMULATED SMS vendor SDK, bought by Campus IT.
// It is already in the repo but nothing uses it yet.
// Note: its API is different from EmailProvider's (it returns a status code).


namespace campus {

struct SentSms {
    std::string phone;
    std::string body;
};

class SmsGateway {
public:
    static constexpr int kAccepted = 0;       // vendor accepted the text
    static constexpr int kInvalidNumber = 21; // vendor rejected the phone number

    // Returns kAccepted (0) if the vendor accepted the text; any other value means rejected.
    int sendText(const std::string& phoneNumber, const std::string& body);

    // ---- simulation controls (shared by every SmsGateway object) ----
    static const std::vector<SentSms>& outbox();
    static int sendAttempts();
    static void reset();

private:
    static std::vector<SentSms> outbox_;
    static int attempts_;
};

}  // namespace campus

// ===================== src/sms_gateway.cpp =====================
namespace campus {

std::vector<SentSms> SmsGateway::outbox_;
int SmsGateway::attempts_ = 0;

int SmsGateway::sendText(const std::string& phoneNumber, const std::string& body) {
    ++attempts_;
    if (phoneNumber.empty()) {
        return kInvalidNumber;
    }
    outbox_.push_back({phoneNumber, body});
    return kAccepted;
}

const std::vector<SentSms>& SmsGateway::outbox() { return outbox_; }

int SmsGateway::sendAttempts() { return attempts_; }

void SmsGateway::reset() {
    outbox_.clear();
    attempts_ = 0;
}

}  // namespace campus

// ===================== src/campus_admin_api.hpp =====================
// campus_admin_api.hpp - everything the campus admin tool can do.
// In C++, a class made only of pure virtual functions ("= 0") plays the
// role of an interface: it is a promise that implementations must keep.



namespace campus {

class CampusAdminAPI {
public:
    virtual ~CampusAdminAPI() = default;

    // Every event with the number of seats still free.
    virtual std::vector<EventSummary> listEvents() const = 0;

    // Books one seat for the attendee and sends a confirmation.
    virtual RegistrationResult registerAttendee(const Attendee& attendee,
                                                const std::string& eventId) = 0;

    // Removes the event and all of its bookings. Returns false if unknown.
    virtual bool deleteEvent(const std::string& eventId) = 0;

    // CSV with one line per attendee: id,name,email  (personal data!)
    virtual std::string exportAttendees(const std::string& eventId) const = 0;
};

}  // namespace campus

// ===================== src/registration_service.hpp =====================
// registration_service.hpp - the heart of CampusConnect.
// It works. Every baseline test passes. Your job is to change it safely.



namespace campus {

class RegistrationService : public CampusAdminAPI {
public:
    void addEvent(const Event& event);

    RegistrationResult registerAttendee(const Attendee& attendee,
                                        const std::string& eventId) override;

    int bookingCount(const std::string& eventId) const;
    bool isNotificationPending(const std::string& attendeeId,
                               const std::string& eventId) const;

    std::vector<EventSummary> listEvents() const override;
    bool deleteEvent(const std::string& eventId) override;
    std::string exportAttendees(const std::string& eventId) const override;

private:
    const Event* findEvent(const std::string& eventId) const;
    const Attendee* findAttendee(const std::string& attendeeId) const;

    std::vector<Event> events_;
    std::vector<Booking> bookings_;
    std::vector<Attendee> attendees_;
};

}  // namespace campus

// ===================== src/registration_service.cpp =====================
namespace campus {

void RegistrationService::addEvent(const Event& event) { events_.push_back(event); }

RegistrationResult RegistrationService::registerAttendee(const Attendee& attendee,
                                                         const std::string& eventId) {
    // Look up the event.
    const Event* event = findEvent(eventId);
    if (event == nullptr) {
        return RegistrationResult::Rejected;
    }

    // One seat per attendee per event.
    for (const Booking& booking : bookings_) {
        if (booking.attendeeId == attendee.id && booking.eventId == eventId) {
            return RegistrationResult::Duplicate;
        }
    }

    // No overbooking.
    if (bookingCount(eventId) >= event->capacity) {
        return RegistrationResult::Rejected;
    }

    // Save the booking. The confirmation is pending until a provider accepts it.
    bookings_.push_back({attendee.id, eventId, true});
    if (findAttendee(attendee.id) == nullptr) {
        attendees_.push_back(attendee);
    }

    // Write the confirmation.
    std::string text = "You are booked for " + event->title + ".";

    // Send it.
    EmailProvider provider;
    bool accepted = provider.send(attendee.email, text);

    if (accepted) {
        bookings_.back().notificationPending = false;
        return RegistrationResult::Booked;
    }
    return RegistrationResult::BookedNotificationPending;
}

int RegistrationService::bookingCount(const std::string& eventId) const {
    return static_cast<int>(std::count_if(
        bookings_.begin(), bookings_.end(),
        [&](const Booking& booking) { return booking.eventId == eventId; }));
}

bool RegistrationService::isNotificationPending(const std::string& attendeeId,
                                                const std::string& eventId) const {
    for (const Booking& booking : bookings_) {
        if (booking.attendeeId == attendeeId && booking.eventId == eventId) {
            return booking.notificationPending;
        }
    }
    return false;  // no booking, so nothing is pending
}

std::vector<EventSummary> RegistrationService::listEvents() const {
    std::vector<EventSummary> summaries;
    for (const Event& event : events_) {
        summaries.push_back({event.id, event.title, event.capacity - bookingCount(event.id)});
    }
    return summaries;
}

bool RegistrationService::deleteEvent(const std::string& eventId) {
    auto it = std::find_if(events_.begin(), events_.end(),
                           [&](const Event& event) { return event.id == eventId; });
    if (it == events_.end()) {
        return false;
    }
    events_.erase(it);
    bookings_.erase(std::remove_if(bookings_.begin(), bookings_.end(),
                                   [&](const Booking& booking) { return booking.eventId == eventId; }),
                    bookings_.end());
    return true;
}

std::string RegistrationService::exportAttendees(const std::string& eventId) const {
    std::string csv = "id,name,email\n";
    for (const Booking& booking : bookings_) {
        if (booking.eventId != eventId) {
            continue;
        }
        if (const Attendee* attendee = findAttendee(booking.attendeeId)) {
            csv += attendee->id + "," + attendee->name + "," + attendee->email + "\n";
        }
    }
    return csv;
}

const Event* RegistrationService::findEvent(const std::string& eventId) const {
    for (const Event& event : events_) {
        if (event.id == eventId) {
            return &event;
        }
    }
    return nullptr;
}

const Attendee* RegistrationService::findAttendee(const std::string& attendeeId) const {
    for (const Attendee& attendee : attendees_) {
        if (attendee.id == attendeeId) {
            return &attendee;
        }
    }
    return nullptr;
}

}  // namespace campus

// ===================== src/kiosk.hpp =====================
// kiosk.hpp - the public screen in the library lobby.
// Anyone walking past can use it. It only shows what's on.



namespace campus {

class Kiosk {
public:
    explicit Kiosk(CampusAdminAPI& api);

    // One line per event, e.g. "Robotics Night | seats left: 2"
    std::string render() const;

private:
    CampusAdminAPI& api_;
};

}  // namespace campus

// ===================== src/kiosk.cpp =====================
namespace campus {

Kiosk::Kiosk(CampusAdminAPI& api) : api_(api) {}

std::string Kiosk::render() const {
    std::string screen = "CampusConnect - What's on\n";
    const auto events = api_.listEvents();
    if (events.empty()) {
        return screen + "No events today.\n";
    }
    for (const EventSummary& event : events) {
        screen += event.title + " | seats left: " + std::to_string(event.seatsLeft) + "\n";
    }
    return screen;
}

}  // namespace campus

// ===================== tests/mini_test.hpp =====================
// mini_test.hpp - a tiny test helper, so you need nothing but a C++17 compiler.
//
//   TEST_CASE(name_that_describes_the_behavior) { ... }
//   CHECK(condition);            // passes when condition is true
//   CHECK_EQ(actual, expected);  // passes when actual == expected
//
// You do not need to change this file.


namespace mini_test {

struct TestCase {
    const char* name;
    void (*body)();
};

inline std::vector<TestCase>& registry() {
    static std::vector<TestCase> tests;
    return tests;
}

inline int& failedChecks() {
    static int count = 0;
    return count;
}

struct Registrar {
    Registrar(const char* name, void (*body)()) { registry().push_back({name, body}); }
};

inline void reportFailure(const char* file, int line, const std::string& expression,
                          const std::string& detail) {
    ++failedChecks();
    std::cout << "    CHECK FAILED at " << file << ":" << line << "\n"
              << "      " << expression << "\n";
    if (!detail.empty()) {
        std::cout << "      " << detail << "\n";
    }
}

inline int runAll() {
    int passed = 0;
    int failed = 0;
    for (const TestCase& test : registry()) {
        const int before = failedChecks();
        test.body();
        if (failedChecks() == before) {
            ++passed;
            std::cout << "[PASS] " << test.name << "\n";
        } else {
            ++failed;
            std::cout << "[FAIL] " << test.name << "\n";
        }
    }
    std::cout << "\n" << registry().size() << " tests, " << passed << " passed, " << failed
              << " failed\n";
    return failed == 0 ? 0 : 1;
}

}  // namespace mini_test

#define TEST_CASE(name)                                                   \
    static void name();                                                   \
    static const mini_test::Registrar name##_registrar(#name, &name);     \
    static void name()

#define CHECK(condition)                                                  \
    do {                                                                  \
        if (!(condition)) {                                               \
            mini_test::reportFailure(__FILE__, __LINE__, #condition, ""); \
        }                                                                 \
    } while (0)

#define CHECK_EQ(actual, expected)                                                         \
    do {                                                                                   \
        const auto& actual_value_ = (actual);                                              \
        const auto& expected_value_ = (expected);                                          \
        if (!(actual_value_ == expected_value_)) {                                         \
            std::ostringstream detail_;                                                    \
            detail_ << "expected: " << expected_value_ << "   actual: " << actual_value_;  \
            mini_test::reportFailure(__FILE__, __LINE__, #actual " == " #expected,         \
                                     detail_.str());                                       \
        }                                                                                  \
    } while (0)

// ===================== tests/test_rig.hpp =====================
// test_rig.hpp - the ONLY place where tests know how CampusConnect is wired.
//
// RULE OF THE GAME
//   When you refactor (inject a notifier, add a formatter, narrow an interface...),
//   update the wiring HERE. Do NOT change the expected values in baseline_tests.cpp.
//   If a baseline test fails, your change broke a promise. Fix the code, not the test.



struct TestRig {
    campus::RegistrationService service;

    TestRig() {
        campus::EmailProvider::reset();
        campus::SmsGateway::reset();
    }

    // ---------- actions ----------
    void addEvent(const std::string& id, const std::string& title, int capacity) {
        service.addEvent({id, title, capacity});
    }

    campus::RegistrationResult registerAttendee(const campus::Attendee& attendee,
                                                const std::string& eventId) {
        return service.registerAttendee(attendee, eventId);
    }

    // ---------- observations ----------
    int bookingCount(const std::string& eventId) const { return service.bookingCount(eventId); }

    bool isNotificationPending(const std::string& attendeeId, const std::string& eventId) const {
        return service.isNotificationPending(attendeeId, eventId);
    }

    // Confirmations the provider ACCEPTED.
    int messagesSent() const { return static_cast<int>(campus::EmailProvider::outbox().size()); }

    // Times the system TRIED to send a confirmation (accepted or not).
    int sendAttempts() const { return campus::EmailProvider::sendAttempts(); }

    std::string lastMessageText() const {
        const auto& outbox = campus::EmailProvider::outbox();
        return outbox.empty() ? "" : outbox.back().text;
    }

    std::string kioskScreen() {
        campus::Kiosk kiosk(service);
        return kiosk.render();
    }

    // ---------- simulation switches ----------
    void simulateEmailOutage() { campus::EmailProvider::setOutage(true); }
};

